arguments.cmd:
cat > /app/output/styles.css <<'EOF'
:root {
  --green: #2d6a4f;
  --green-dark: #1b4d38;
  --green-soft: #d8f3dc;
  --cream: #fefae0;
  --cream-2: #fffdf0;
  --orange: #f4a261;
  --terracotta: #d66a4c;
  --yellow: #f6d365;
  --ink: #243228;
  --muted: #647267;
  --white: #ffffff;
  --shadow: 0 22px 60px rgba(45, 106, 79, 0.14);
  --shadow-soft: 0 14px 34px rgba(45, 106, 79, 0.12);
  --radius-xl: 34px;
  --radius-lg: 24px;
  --radius-md: 18px;
  --max: 1180px;
}

* { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background:
    radial-gradient(circle at 14% 8%, rgba(244, 162, 97, 0.2), transparent 28rem),
    radial-gradient(circle at 88% 15%, rgba(216, 243, 220, 0.9), transparent 24rem),
    var(--cream);
  line-height: 1.6;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(45, 106, 79, 0.08) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, black, transparent 62%);
  z-index: -1;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

button, input { font: inherit; }

button { cursor: pointer; }

h1, h2, h3 {
  font-family: Nunito, Inter, sans-serif;
  line-height: 1.02;
  color: var(--green-dark);
  margin: 0;
}

h1 {
  font-size: clamp(3.2rem, 8vw, 6.9rem);
  letter-spacing: -0.065em;
  max-width: 860px;
}

h2 {
  font-size: clamp(2.1rem, 4.3vw, 4rem);
  letter-spacing: -0.04em;
}

h3 {
  font-size: 1.35rem;
  letter-spacing: -0.02em;
}

p { margin: 0; color: var(--muted); }

.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  z-index: 100;
  background: var(--green-dark);
  color: var(--white);
  padding: 0.75rem 1rem;
  border-radius: 999px;
}

.skip-link:focus { top: 1rem; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  padding: 1rem clamp(1rem, 3vw, 2rem);
  background: rgba(254, 250, 224, 0.82);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(45, 106, 79, 0.1);
}

.nav-shell {
  max-width: var(--max);
  margin: 0 auto;
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-family: Nunito, Inter, sans-serif;
  font-weight: 900;
  font-size: 1.25rem;
  color: var(--green-dark);
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 16px;
  color: var(--cream);
  background: linear-gradient(135deg, var(--green), var(--green-dark));
  box-shadow: 0 10px 22px rgba(45, 106, 79, 0.18);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  list-style: none;
  padding: 0.35rem;
  margin: 0;
  border: 1px solid rgba(45, 106, 79, 0.12);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.54);
}

.nav-links a {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  padding: 0 1rem;
  border-radius: 999px;
  color: var(--green-dark);
  font-weight: 700;
  transition: background 180ms ease, color 180ms ease, transform 180ms ease;
}

.nav-links a:hover,
.nav-links a:focus-visible {
  background: var(--green);
  color: var(--white);
  transform: translateY(-1px);
}

.menu-toggle {
  display: none;
  width: 48px;
  height: 48px;
  border: 0;
  border-radius: 16px;
  background: var(--green);
  padding: 12px;
}

.menu-toggle span:not(.sr-only) {
  display: block;
  height: 2px;
  margin: 5px 0;
  background: var(--cream);
  border-radius: 99px;
}

.hero {
  max-width: var(--max);
  margin: 0 auto;
  padding: clamp(3rem, 7vw, 6rem) clamp(1rem, 3vw, 2rem) 3.5rem;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(320px, 0.78fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.75rem;
  color: var(--terracotta);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.78rem;
}

.eyebrow::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 99px;
  background: var(--orange);
  box-shadow: 13px 0 0 var(--yellow);
}

.hero-subtitle {
  max-width: 650px;
  margin-top: 1.15rem;
  font-size: clamp(1.08rem, 2vw, 1.35rem);
  color: #526057;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 2rem;
}

.btn {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  min-height: 52px;
  padding: 0.85rem 1.25rem;
  border: 0;
  border-radius: 999px;
  font-weight: 900;
  transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.btn:hover,
.btn:focus-visible {
  transform: translateY(-2px);
}

.btn-primary {
  color: var(--cream);
  background: var(--green);
  box-shadow: 0 16px 30px rgba(45, 106, 79, 0.2);
}

.btn-primary:hover,
.btn-primary:focus-visible { background: var(--green-dark); }

.btn-secondary {
  color: var(--green-dark);
  background: var(--yellow);
  box-shadow: 0 16px 30px rgba(246, 211, 101, 0.24);
}

.hero-market {
  position: relative;
  min-height: 560px;
}

.hero-image-large {
  width: 100%;
  height: 540px;
  border-radius: 46px;
  background:
    linear-gradient(to bottom, rgba(45, 106, 79, 0.05), rgba(45, 106, 79, 0.28)),
    url("https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1100&q=85") center/cover;
  box-shadow: var(--shadow);
  border: 10px solid rgba(255, 255, 255, 0.62);
}

.hero-card,
.price-tag {
  position: absolute;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(45, 106, 79, 0.12);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(10px);
}

.floating-card {
  left: -1.5rem;
  bottom: 4.8rem;
  width: min(260px, 75%);
  padding: 1rem;
  display: grid;
  gap: 0.15rem;
}

.floating-card strong { color: var(--green-dark); }
.floating-card span:last-child { color: var(--muted); font-size: 0.92rem; }

.icon-bubble {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin-bottom: 0.35rem;
  border-radius: 16px;
  background: var(--green-soft);
}

.price-tag {
  top: 2rem;
  right: -1rem;
  padding: 0.9rem 1.15rem;
  font-weight: 900;
  color: var(--green-dark);
}

.stats-banner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 1.25rem;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--green-dark), var(--green));
  box-shadow: var(--shadow);
}

.stat-item {
  min-height: 180px;
  padding: 1.4rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-radius: 26px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.14);
}

.stat-item strong {
  font-family: Nunito, Inter, sans-serif;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 0.95;
  color: var(--yellow);
}

.stat-item span {
  margin-top: 0.45rem;
  color: var(--white);
  font-weight: 900;
  font-size: 1.05rem;
}

.stat-item small {
  margin-top: 0.45rem;
  color: rgba(255, 255, 255, 0.74);
}

.section {
  max-width: var(--max);
  margin: 0 auto;
  padding: clamp(4rem, 8vw, 7rem) clamp(1rem, 3vw, 2rem) 0;
}

.section-heading {
  margin-bottom: 2rem;
}

.section-heading p:not(.eyebrow) {
  max-width: 660px;
  margin-top: 0.75rem;
  font-size: 1.05rem;
}

.split-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
}

.centered {
  text-align: center;
  display: grid;
  justify-items: center;
}

.carousel-controls {
  display: flex;
  gap: 0.65rem;
}

.carousel-btn {
  width: 54px;
  height: 54px;
  border: 0;
  border-radius: 19px;
  color: var(--green-dark);
  background: var(--white);
  font-size: 1.5rem;
  font-weight: 900;
  box-shadow: var(--shadow-soft);
  transition: transform 180ms ease, background 180ms ease, color 180ms ease;
}

.carousel-btn:hover,
.carousel-btn:focus-visible {
  transform: translateY(-2px) scale(1.03);
  background: var(--orange);
  color: var(--white);
}

.product-carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(285px, 31%);
  gap: 1.25rem;
  overflow-x: auto;
  padding: 0.2rem 0.2rem 1.6rem;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--orange) rgba(45, 106, 79, 0.08);
}

.product-card {
  scroll-snap-align: start;
  overflow: hidden;
  border-radius: 30px;
  background: var(--white);
  border: 1px solid rgba(45, 106, 79, 0.1);
  box-shadow: var(--shadow-soft);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.product-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 22px 44px rgba(45, 106, 79, 0.16);
}

.product-card img {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.product-content {
  min-height: 250px;
  padding: 1.35rem;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.product-kicker {
  align-self: flex-start;
  padding: 0.28rem 0.68rem;
  border-radius: 999px;
  color: var(--green-dark);
  background: var(--green-soft);
  font-weight: 900;
  font-size: 0.78rem;
}

.product-content p { flex: 1; }

.product-content strong,
.seasonal-card strong {
  font-family: Nunito, Inter, sans-serif;
  font-size: 1.65rem;
  color: var(--terracotta);
}

.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.seasonal-card {
  padding: 1.45rem;
  min-height: 310px;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  border-radius: 30px;
  border: 1px solid rgba(45, 106, 79, 0.1);
  box-shadow: var(--shadow-soft);
}

.seasonal-card span:first-child {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border-radius: 21px;
  background: rgba(255, 255, 255, 0.54);
  font-size: 1.7rem;
}

.seasonal-card p { flex: 1; color: rgba(36, 50, 40, 0.72); }
.highlight-yellow { background: #fff3b0; }
.highlight-green { background: #d8f3dc; }
.highlight-cream { background: #fffdf0; }
.highlight-orange { background: #ffd0b6; }

.category-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.category-card {
  position: relative;
  min-height: 260px;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  justify-content: end;
  overflow: hidden;
  border-radius: 30px;
  background: var(--bg) center/cover;
  color: var(--white);
  box-shadow: var(--shadow-soft);
  transform: translateZ(0);
  transition: transform 220ms ease, box-shadow 220ms ease;
}

.category-card:nth-child(1),
.category-card:nth-child(2) { grid-column: span 3; }
.category-card:nth-child(3),
.category-card:nth-child(4),
.category-card:nth-child(5) { grid-column: span 2; }

.category-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(27, 77, 56, 0.84), rgba(27, 77, 56, 0.08));
  transition: background 220ms ease;
}

.category-card::after {
  content: "Explore " attr(aria-label);
  position: absolute;
  inset: 1rem;
  display: grid;
  place-items: center;
  border-radius: 24px;
  background: rgba(45, 106, 79, 0.72);
  color: var(--cream);
  font-family: Nunito, Inter, sans-serif;
  font-size: clamp(1.6rem, 3vw, 2.5rem);
  font-weight: 900;
  text-align: center;
  opacity: 0;
  transform: scale(0.94);
  transition: opacity 220ms ease, transform 220ms ease;
  backdrop-filter: blur(3px);
}

.category-card span,
.category-card small {
  position: relative;
  z-index: 1;
}

.category-card span {
  font-family: Nunito, Inter, sans-serif;
  font-size: 1.55rem;
  line-height: 1;
  font-weight: 900;
}

.category-card small {
  max-width: 440px;
  margin-top: 0.5rem;
  color: rgba(255, 255, 255, 0.82);
  font-weight: 600;
}

.category-card:hover,
.category-card:focus-visible {
  transform: scale(1.025);
  box-shadow: 0 24px 48px rgba(45, 106, 79, 0.18);
}

.category-card:hover::after,
.category-card:focus-visible::after {
  opacity: 1;
  transform: scale(1);
}

.locator-panel,
.about-card,
.newsletter-inner {
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow);
}

.locator-panel {
  padding: clamp(1.4rem, 4vw, 3rem);
  display: grid;
  gap: 1.5rem;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(216, 243, 220, 0.92)),
    url("https://images.unsplash.com/photo-1604719312566-8912e9227c6a?auto=format&fit=crop&w=1200&q=80") center/cover;
  border: 1px solid rgba(45, 106, 79, 0.12);
}

.locator-copy p:not(.eyebrow) { max-width: 540px; margin-top: 0.65rem; }

.locator-form,
.newsletter-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.8rem;
  align-items: start;
}

input {
  width: 100%;
  min-height: 56px;
  border: 2px solid rgba(45, 106, 79, 0.12);
  border-radius: 999px;
  padding: 0 1.2rem;
  background: rgba(255, 255, 255, 0.92);
  color: var(--ink);
  outline: 0;
}

input:focus {
  border-color: var(--orange);
  box-shadow: 0 0 0 4px rgba(244, 162, 97, 0.18);
}

.store-results {
  display: grid;
  gap: 0.85rem;
  animation: reveal 240ms ease both;
}

.store-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto auto;
  gap: 1rem;
  align-items: center;
  padding: 1rem;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(45, 106, 79, 0.1);
}

.store-card h3 { font-size: 1.1rem; }
.store-card p { font-size: 0.92rem; }
.store-card span { color: var(--muted); font-weight: 700; }
.store-card strong { color: var(--green-dark); }
.store-card a { color: var(--terracotta); font-weight: 900; }

.about-card {
  padding: clamp(1.5rem, 4vw, 3rem);
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 2rem;
  align-items: center;
  background: var(--white);
  border: 1px solid rgba(45, 106, 79, 0.1);
}

.about-card p:last-child { font-size: 1.08rem; }

.newsletter {
  max-width: var(--max);
  margin: 0 auto;
  padding: clamp(4rem, 8vw, 7rem) clamp(1rem, 3vw, 2rem);
}

.newsletter-inner {
  padding: clamp(1.5rem, 4vw, 3.2rem);
  display: grid;
  grid-template-columns: 0.82fr 1fr;
  gap: 2rem;
  align-items: center;
  background: linear-gradient(135deg, var(--orange), #ffd86b);
}

.newsletter-inner h2,
.newsletter-inner p,
.newsletter-inner .eyebrow { color: var(--green-dark); }
.newsletter-inner .eyebrow::before { background: var(--green); box-shadow: 13px 0 0 var(--cream); }

.newsletter-form {
  position: relative;
}

.confirmation {
  grid-column: 1 / -1;
  padding: 0.85rem 1rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--green-dark);
  font-weight: 800;
  animation: reveal 240ms ease both;
}

.site-footer {
  padding: 3rem clamp(1rem, 3vw, 2rem) 2rem;
  background: var(--green-dark);
  color: rgba(255, 255, 255, 0.78);
}

.footer-grid {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.6fr repeat(4, 1fr);
  gap: 2rem;
}

.site-footer .brand,
.site-footer h2 { color: var(--cream); }
.site-footer .brand-mark { background: var(--orange); color: var(--green-dark); }
.site-footer h2 { margin-bottom: 0.8rem; font-size: 1.05rem; letter-spacing: 0; }
.site-footer a { display: block; margin: 0.38rem 0; color: rgba(255, 255, 255, 0.78); }
.site-footer a:hover,
.site-footer a:focus-visible { color: var(--yellow); }
.footer-brand p { max-width: 330px; margin-top: 1rem; color: rgba(255, 255, 255, 0.72); }
.footer-bottom { max-width: var(--max); margin: 2.5rem auto 0; color: rgba(255, 255, 255, 0.65); }

@keyframes reveal {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@media (max-width: 980px) {
  .hero,
  .newsletter-inner,
  .about-card {
    grid-template-columns: 1fr;
  }

  .hero-market { min-height: 460px; }
  .hero-image-large { height: 440px; }
  .stats-banner { grid-template-columns: repeat(2, 1fr); margin-inline: 1rem; }
  .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
  .product-carousel { grid-auto-columns: minmax(280px, 44%); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
}

@media (max-width: 760px) {
  .site-header { padding: 0.7rem 1rem; }
  .menu-toggle { display: block; }
  .nav-shell { min-height: 58px; }
  .nav-links {
    position: absolute;
    left: 1rem;
    right: 1rem;
    top: calc(100% + 0.4rem);
    display: none;
    flex-direction: column;
    align-items: stretch;
    padding: 0.8rem;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: var(--shadow-soft);
  }

  .nav-links.is-open { display: flex; }
  .nav-links a { justify-content: center; }
  .hero { padding-top: 2.5rem; }
  .hero-market { min-height: 360px; }
  .hero-image-large { height: 340px; border-radius: 34px; }
  .floating-card { left: 0.75rem; bottom: 1rem; }
  .price-tag { right: 0.75rem; top: 1rem; }
  .split-heading { align-items: start; flex-direction: column; }
  .product-carousel { grid-auto-columns: minmax(260px, 82%); }
  .stats-banner,
  .seasonal-grid,
  .category-grid,
  .locator-form,
  .newsletter-form,
  .store-card {
    grid-template-columns: 1fr;
  }
  .category-card,
  .category-card:nth-child(1),
  .category-card:nth-child(2),
  .category-card:nth-child(3),
  .category-card:nth-child(4),
  .category-card:nth-child(5) { grid-column: auto; }
  .category-card { min-height: 220px; }
  .store-card { align-items: start; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 460px) {
  h1 { font-size: 3rem; }
  .hero-actions .btn,
  .locator-form .btn,
  .newsletter-form .btn { width: 100%; }
  .stats-banner { grid-template-columns: 1fr; }
  .seasonal-grid { grid-template-columns: 1fr; }
  .product-card img { height: 190px; }
  .product-content { min-height: 230px; }
}
EOF

cat > /app/output/script.js <<'EOF'
const carousel = document.querySelector('#product-carousel');
const prevButton = document.querySelector('#carousel-prev');
const nextButton = document.querySelector('#carousel-next');
const locatorForm = document.querySelector('#locator-form');
const storeResults = document.querySelector('#store-results');
const newsletterForm = document.querySelector('#newsletter-form');
const newsletterConfirmation = document.querySelector('#newsletter-confirmation');
